python3 << 'EOF'
import json

# Let me search more carefully - looking at structure
data = json.load(open('/app/resources/treasury_bulletin_2013_06.json'))

# Get page numbers
pages_with_esf = set()
elements = data.get('document', {}).get('elements', [])
for i, elem in enumerate(elements):
    if 'content' in elem and elem['content']:
        c = str(elem['content'])
        if 'Total assets' in c and ('2012' in c or '2013' in c or 'Dec' in c):
            # Get page numbers
            if 'bbox' in elem:
                for b in elem.get('bbox', []):
                    if 'page_id' in b:
                        pages_with_esf.add(b['page_id'])
            print(f"Element {i}: {c[:100]}")
            print(f"  Page: {[b.get('page_id') for b in elem.get('bbox', [])]}")

print(f"\nPages with ESF total assets: {sorted(pages_with_esf)}")
EOF
